package com.transportlogistics.app.freight.manifest.domain.model;
import com.transportlogistics.app.freight.order.ports.inbound.FreightOrderLookup;import com.transportlogistics.app.shared.domain.*;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class CargoManifestTest {private final UUID lineId=UUID.randomUUID();private final OffsetDateTime now=OffsetDateTime.parse("2026-08-25T00:00:00Z");
 @Test void validItemMakesManifestReadyAndFinalizable(){var manifest=manifest(List.of(item(false,false)));var expected=expected();assertTrue(manifest.validate(expected).isEmpty());var finalized=manifest.finalizeManifest(expected,"finalizer",now.plusHours(1));assertTrue(finalized.finalized());assertEquals("finalizer",finalized.finalizedBy());assertThrows(ConflictException.class,()->finalized.addItem(item(false,false),"editor",now));}
 @Test void conditionalCustomsAndHazmatAreActionable(){var customs=manifest(List.of(new CargoManifestItem(UUID.randomUUID(),lineId,"Cargo",BigDecimal.TEN,"Wrapped","SUPPLIER.CODE",true,null,true,null,null)));var codes=customs.validate(expected()).stream().map(ManifestValidationFailure::code).toList();assertTrue(codes.contains("CUSTOMS_INFORMATION_REQUIRED"));assertTrue(codes.contains("HAZARDOUS_CLASSIFICATION_REQUIRED"));assertTrue(codes.contains("HAZARDOUS_DETAILS_REQUIRED"));assertThrows(BusinessRuleException.class,()->customs.finalizeManifest(expected(),"actor",now));}
 @Test void flagsKnownUnmanifestedCargo(){var partial=manifest(List.of(new CargoManifestItem(UUID.randomUUID(),lineId,"Cargo",BigDecimal.ONE,"Wrapped","CODE",false,null,false,null,null)));assertEquals("UNMANIFESTED_CARGO",partial.validate(expected()).getFirst().code());}
 @Test void itemInvariantsRejectInvalidData(){assertThrows(BusinessRuleException.class,()->new CargoManifestItem(UUID.randomUUID(),lineId,"",BigDecimal.ZERO,"","",false,null,false,null,null));}
 private CargoManifest manifest(List<CargoManifestItem> items){return new CargoManifest(UUID.randomUUID(),"CM-2026-000001",UUID.randomUUID(),"FO-2026-000001",items,0,now,now,"creator","creator",null,null);}private CargoManifestItem item(boolean customs,boolean hazmat){return new CargoManifestItem(UUID.randomUUID(),lineId,"Cargo",BigDecimal.TEN,"Wrapped by supplier","SUPPLIER.CODE",customs,customs?"CUS-1":null,hazmat,hazmat?"UN.1203":null,hazmat?"Supplier declaration":null);}private List<FreightOrderLookup.ExpectedLine> expected(){return List.of(new FreightOrderLookup.ExpectedLine(lineId,"Cargo",BigDecimal.TEN));}}
